public class Example {
    public static void main(String[] args) {
        System.out.println("=== 01: Integer Cache Trap ===");
        Integer a = 100;
        Integer b = 100;
        System.out.println("100 == 100: " + (a == b)); // true (Cached)

        Integer c = 500;
        Integer d = 500;
        System.out.println("500 == 500: " + (c == d)); // false (Separate heap objects!)
        System.out.println("500 equals 500: " + c.equals(d)); // true
    }
}

